recorder:
// Recorder for the node-files-*.controls.json files. Every scenario is the body of an async function of
// (fs, h) that the test runs again, unchanged, against the emulated fs. Run with Node 24.18.1 on a tmpfs
// (its readdir order is the byte order the file service's readdir has):
//   docker run --rm --tmpfs /work -v "$PWD":/w:ro node:24.18.1-alpine node /w/record.cjs /w/sc/<set> > node-files-<set>.controls.json
const fs = require("fs"), path = require("path"), util = require("util");
const dir = process.argv[2], out = {};
function describe(e) {
  if (!(e instanceof Error)) return { thrown: String(e) };
  const d = { name: e.name, ctor: e.constructor.name, message: e.message };
  for (const k of ["code", "errno", "syscall", "path", "dest"]) if (e[k] !== undefined) d[k] = e[k];
  return d;
}
function helpers(warnings) {
  return {
    Buffer, custom: util.promisify.custom, warnings, err: describe,
    attempt(fn) { try { return { ok: fn() }; } catch (e) { return { error: describe(e) }; } },
    async attemptAsync(fn) { try { return { ok: await fn() }; } catch (e) { return { error: describe(e) }; } },
    turn: () => new Promise(resolve => setImmediate(resolve)),
    // Long enough for several polls of a 20 ms stat watcher; the replay fires its timer instead.
    wait: () => new Promise(resolve => setTimeout(resolve, 150)),
    dirent: d => d === null ? null : [Buffer.isBuffer(d.name) ? { hex: d.name.toString("hex") } : d.name, Buffer.isBuffer(d.parentPath) ? { hex: d.parentPath.toString("hex") } : d.parentPath,
      d.isDirectory() ? "dir" : d.isSymbolicLink() ? "link" : d.isFile() ? "file" : "other"],
    fn: f => typeof f === "function" ? [f.name, f.length] : typeof f,
  };
}
(async () => {
  for (const file of fs.readdirSync(dir).sort()) {
    for (const name of fs.readdirSync("/work")) fs.rmSync("/work/" + name, { recursive: true, force: true });
    process.chdir("/work");
    const warnings = [], onWarning = w => warnings.push([w.name, w.message]);
    process.on("warning", onWarning);
    const source = fs.readFileSync(path.join(dir, file), "utf8");
    const result = await new Function("fs", "h", "return (async () => {" + source + "\n})()")(fs, helpers(warnings));
    process.off("warning", onWarning);
    out[file.replace(/\.js$/, "")] = { source, result: JSON.parse(JSON.stringify(result)) };
  }
  console.log(JSON.stringify({ node: process.version, recorder: fs.readFileSync(__filename, "utf8"), scenarios: out }, null, 1));
})();

